select jsonb_build_object('signatures',jsonb_agg(jsonb_build_object('signature',w.signature,'present',p.oid is not null,'definition_md5',case when p.oid is null then null else md5(pg_get_functiondef(p.oid)) end,'owner',case when p.oid is null then null else pg_get_userbyid(p.proowner) end,'acl',p.proacl::text) order by w.signature)) from(values ('private.weekly_source_sha256_text_v1(text,text)'),('private.weekly_source_sha256_jsonb_v1(text,jsonb)'),('private.weekly_source_final_value_vector_v1(jsonb)'),('private.weekly_source_authority_subset_v1(jsonb)'),('private.weekly_source_final_state_fingerprint_v1(jsonb)'),('private.weekly_source_invoice_economics_fingerprint_v1(jsonb,text,numeric)'),('private.weekly_source_magnit_bucket_assert_v1(jsonb,jsonb)'),('private.weekly_source_magnit_contract_price_assert_v1(jsonb,jsonb)')) w(signature) left join pg_proc p on p.oid=to_regprocedure(w.signature);